checkResultURL(url) {
  if (
    this._authorizationState &&
    this._authorizationState !== url.searchParams.get("state")
  ) {
    return false;
  }
  const iss = url.searchParams.get("iss");
  if (this.issuerIdentifier) {
    if (iss !== this.issuerIdentifier) {
      log.warn(
        `Unexpected issuer: requested ${this.issuerIdentifier}, found ${iss}.`
      );
      return false;
    }
  } else if (iss) {
    // An issuer field was present when not required. This means either:
    //   1. An OAuth provider that doesn't advertise RFC 9207 support is
    //      behaving maliciously and trying to trick us into sending it
    //      credentials for another provider who does, or
    //   2. The provider has implemented support for RFC 9207 since
    //      OAuth2Providers.sys.mjs was last updated for them.
    // The spec tells us to assume the first scenario, but that would cause
    // quite a bit of breakage until an update can ship, so we instead do a
    // best effort check that the issuer and authorization endpoint are using
    // the same domain (which is not technically required, but has been true
    // for all providers so far).
    if (new URL(iss).origin != new URL(this.authorizationEndpoint).origin) {
      log.warn(`Unexpected issuer: expected no issuer, found ${iss}.`);
      return false;
    }
  }
  return url.searchParams.has("code");
},

/**
 * @param {string} aURL - Redirection URI with additional parameters.
 */
onAuthorizationReceived(aURL) {
  log.info("OAuth2 authorization response received: url=" + aURL);
  const url = new URL(aURL);
  // Check the state param matches the value we created earlier.
  const expectedState = this._authorizationState;
  this._authorizationState = null;
  if (expectedState && url.searchParams.get("state") !== expectedState) {
    this.onAuthorizationFailed(
      Cr.NS_ERROR_FAILURE,
      '{ "error": "invalid_state" }',
      "state mismatch"
    );
    return;
  }
  if (this.checkResultURL(url)) {
    // @see RFC 6749 section 4.1.2: Authorization Response
    this._authorizationReceived = true;
    this.requestAccessToken(url.searchParams.get("code"), false);
  } else {
    // @see RFC 6749 section 4.1.2.1: Error Response
    let reason = "authorization failed";
    if (url.searchParams.has("error")) {
      const error = url.searchParams.get("error");
      let errorDescription = url.searchParams.get("error_description") || "";
      if (error == "invalid_scope") {
        errorDescription += ` Invalid scope: ${this.scope}.`;
        reason = "invalid scope";
      }
      if (url.searchParams.has("error_uri")) {
        errorDescription += ` See ${url.searchParams.get("error_uri")}.`;
      }
      log.error(`Authorization error [${error}]: ${errorDescription}`);
    }
    this.onAuthorizationFailed(null, aURL, reason);
  }
},

onAuthorizationFailed(aError, aData, aTelemetryReason) {
  if (aTelemetryReason == "cancelled" && this._authorizationReceived) {
    // The authorization code was already received and the token exchange is
    // in progress. A teardown-triggered cancel must not clobber the pending
    // result or reject the in-flight token request.
    return;
  }
  this.recordTelemetry(aTelemetryReason);
  this._reject(aData);
},
